/**
 * Auto-update all PNG import statements to WebP
 * Only for icons that have been optimized to WebP
 * Run: node update-webp-imports.js
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const iconsDir = path.join(__dirname, 'src/assets/icons');
const publicDir = path.join(__dirname, 'public');
const srcDir = path.join(__dirname, 'src');

// Icons that now have .webp versions (generated by optimize-images.js)
const webpConverted = [
  'c1', 'c31', 'c4', 'c2',
  's1', 's2', 's3', 's4',
  'foot1', 'foot2', 'foot3', 'foot4', 'foot11', 'foot22', 'foot33',
  'v1', 't1',
  'footerright', 'footerbot', 'leafright', 'leafg', 'parlia', 'main', 'main22',
  'notes', 'pdf',
  'a1', 'a2', 'a3', 'a4', 'a5', 'a6',
  'icon1', 'icon2', 'icon3', 'icon4',
  'h1',
];

// Walk all .tsx, .ts, .jsx, .js files in src/
function getAllFiles(dir, extensions = ['.tsx', '.ts', '.jsx', '.js']) {
  let results = [];
  const items = fs.readdirSync(dir);
  for (const item of items) {
    const full = path.join(dir, item);
    const stat = fs.statSync(full);
    if (stat.isDirectory() && item !== 'node_modules' && item !== '.next') {
      results = results.concat(getAllFiles(full, extensions));
    } else if (extensions.some(ext => item.endsWith(ext))) {
      results.push(full);
    }
  }
  return results;
}

let totalFilesChanged = 0;
let totalReplacements = 0;

const files = getAllFiles(srcDir);

for (const filePath of files) {
  let content = fs.readFileSync(filePath, 'utf-8');
  let changed = false;
  let replacements = 0;

  for (const name of webpConverted) {
    // Match: from '@/assets/icons/NAME.png'  or  from "@/assets/icons/NAME.png"
    const pngPattern = new RegExp(`(@/assets/icons/${name})\\.png`, 'g');
    if (pngPattern.test(content)) {
      content = content.replace(new RegExp(`(@/assets/icons/${name})\\.png`, 'g'), `$1.webp`);
      changed = true;
      replacements++;
    }
  }

  // Also update public logo.webp references (if you decide to use next/image)
  // logo.png and logo1.png are in /public — Next.js Image handles optimization auto

  if (changed) {
    fs.writeFileSync(filePath, content, 'utf-8');
    totalFilesChanged++;
    totalReplacements += replacements;
    console.log(`✅ Updated ${replacements} import(s) in: ${path.relative(__dirname, filePath)}`);
  }
}

console.log(`\n🎉 Done! Updated ${totalReplacements} import(s) across ${totalFilesChanged} file(s)`);
console.log('🔄 Restart your dev server: npm run dev');
